  const addItem = async (type,data={}) => saveItem({id:uid(),type,createdAt:nowISO(),updatedAt:nowISO(),...data});
  const removeItem = async item => {if(!item)return;item.deletedAt=nowISO();await saveItem(item);toast(`${typeLabel(item.type)} moved to Trash`);render();};
  const restoreItem = async item => {delete item.deletedAt;await saveItem(item);toast('Item restored');render();};
  const permanentlyDelete = async item => {if(item.type==='file'){await removeStoredFile(item.id);}await storeRequest('items','readwrite','delete',item.id);state.items=state.items.filter(x=>x.id!==item.id);render();};
  const saveBlobFallback = async (id,blob) => storeRequest('blobs','readwrite','put',{id,blob});
  const readStoredFile = async item => {if(item.storage==='opfs'&&navigator.storage?.getDirectory){try{const root=await navigator.storage.getDirectory();const dir=await root.getDirectoryHandle('nexus-files');const handle=await dir.getFileHandle(item.id);return await handle.getFile();}catch{}}const row=await storeRequest('blobs','readonly','get',item.id);if(row?.blob)return row.blob;if((item.size||0)>0)throw new Error(`The stored content for “${item.name}” is missing. Restore a backup or remove the broken file record.`);return new Blob([],{type:item.mime||'application/octet-stream'});};
  const writeStoredFile = async (id,blob) => {if(navigator.storage?.getDirectory){try{const root=await navigator.storage.getDirectory();const dir=await root.getDirectoryHandle('nexus-files',{create:true});const handle=await dir.getFileHandle(id,{create:true});const writer=await handle.createWritable();await writer.write(blob);await writer.close();return 'opfs';}catch(err){console.warn('OPFS unavailable; using IndexedDB fallback.',err);}}await saveBlobFallback(id,blob);return 'idb';};
  const removeStoredFile = async id => {try{const root=await navigator.storage?.getDirectory?.();const dir=await root?.getDirectoryHandle('nexus-files');await dir?.removeEntry(id);}catch{}await storeRequest('blobs','readwrite','delete',id).catch(()=>{});};
  const saveFile = async (file, extra={}) => {const id=uid();const storage=await writeStoredFile(id,file);await addItem('file',{id,name:file.name,size:file.size,mime:file.type||'application/octet-stream',parentId:extra.parentId??state.filesFolder,favorite:false,storage,tags:[],fileModified:file.lastModified||Date.now()});};
  const loadSettings = async () => (await metaGet('settings')) || {};
  const saveSettings = async () => metaPut('settings',state.settings);
  const renderNav = () => {
    const target=$('#navigation');target.innerHTML=nav.map(group=>`<div class="nav-section">${group.group}</div>${group.items.map(([key,label,ico])=>`<button class="nav-item ${state.section===key?'active':''}" data-nav="${key}"><span class="nav-icon">${icon(ico)}</span><span>${label}</span>${key==='tasks'&&liveItems('task').filter(t=>t.dueDate===localDate()).length?`<span class="nav-count">${liveItems('task').filter(t=>t.dueDate===localDate()&&!t.completed).length}</span>`:''}</button>`).join('')}`).join('');
  };
  const updateNav = () => {renderNav();$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.section));};
  const updateShell = () => {$('#pageLabel').textContent=({home:'Home',myday:'My Day',search:'Search',files:'My Files',documents:'Documents',spreadsheets:'Spreadsheets',presentations:'Presentations',notes:'Notes',bookmarks:'Bookmarks',collections:'Collections',trash:'Trash',calendar:'Calendar',tasks:'Tasks & Reminders',agenda:'Agenda',email:'Email',settings:'Settings',privacy:'Privacy & data'})[state.section]||'Workspace';$('#workspaceName').textContent=state.workspaceName;updateNav();};
  const toast = (message,error=false) => {const box=document.createElement('div');box.className=`toast${error?' error':''}`;box.textContent=message;$('#toastRegion').append(box);setTimeout(()=>box.remove(),3300);};
  const empty = (title,description,ico='files',button='') => `<div class="empty-state"><span class="empty-orb">${icon(ico)}</span><strong>${escapeHTML(title)}</strong><p>${escapeHTML(description)}</p>${button?`<div style="margin-top:12px">${button}</div>`:''}</div>`;
  const pageHeading = (title,desc,actions='') => `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;
  const metric = (label,value,note,ico) => `<article class="card metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon">${icon(ico)}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></article>`;
  const button = (label,ico,action,primary=false,extra='') => `<button class="button ${primary?'button-primary':''} ${extra}" data-action="${action}">${icon(ico)}<span>${label}</span></button>`;
  const itemDate = item => item.dueDate||item.startDate||item.updatedAt?.slice(0,10)||item.createdAt?.slice(0,10);
  const searchText = item => [item.name,item.title,item.description,item.content,item.url,item.tags?.join(' '),item.dueDate,item.startDate].filter(Boolean).join(' ').toLowerCase();
  const render = () => {const active=document.activeElement;const focusId=active&&$('#content').contains(active)?active.id:'';const start=active&&typeof active.selectionStart==='number'?active.selectionStart:null;const end=active&&typeof active.selectionEnd==='number'?active.selectionEnd:null;updateShell();const content=$('#content');content.innerHTML=(views[state.section]||views.home)();const accent=$('#accentSelect');if(accent&&state.settings.accent)accent.value=safeColor(state.settings.accent);const reminder=$('#defaultReminder');if(reminder&&state.settings.defaultReminder!=null)reminder.value=String(state.settings.defaultReminder);if(focusId){const next=document.getElementById(focusId);if(next){next.focus({preventScroll:true});if(start!==null&&next.setSelectionRange)try{next.setSelectionRange(start,end);}catch{}}}};
  const navigate = section => {state.section=section;state.query='';$('#globalSearch').value='';$('#sidebar').classList.remove('open');render();};
  const modal = ({title,body,footer='',wide=false}) => {$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><header class="modal-head"><h2>${escapeHTML(title)}</h2><button class="close-button" data-action="close-modal" aria-label="Close">${icon('x')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-foot">${footer}</footer>`:''}</section></div>`;};
  const flushActiveEditor = () => {const root=$('#modalRoot');for(const key of ['document-save','note-save','sheet-save','presentation-save'])clearTimeout(debounceTimers.get(key));const doc=root.dataset.documentId&&getItem(root.dataset.documentId);if(doc&&$('#docEditor')){doc.name=$('#docName').value.trim()||'Untitled document';doc.content=sanitizeRichHTML($('#docEditor').innerHTML);void saveItem(doc);}const note=root.dataset.noteId&&getItem(root.dataset.noteId);if(note&&$('#noteTitle')){note.name=$('#noteTitle').value.trim()||'Untitled note';note.content=$('#noteContent').value;note.tags=$('#noteTags').value.split(',').map(x=>x.trim()).filter(Boolean);note.pinned=$('#notePinned').checked;void saveItem(note);}const sheet=root.dataset.sheetId&&getItem(root.dataset.sheetId);if(sheet&&$('#sheetName')){sheet.name=$('#sheetName').value.trim()||'Untitled spreadsheet';sheet.cells=readSheetCells();void saveItem(sheet);}const presentation=root.dataset.presentationId&&getItem(root.dataset.presentationId);if(presentation&&$('#presName')){syncSlideEdits(presentation);presentation.name=$('#presName').value.trim()||'Untitled presentation';void saveItem(presentation);}};
  const closeModal = () => {flushActiveEditor();const url=$('#modalRoot').dataset.previewUrl;if(url)URL.revokeObjectURL(url);$('#modalRoot').innerHTML='';};
  const actionButton = (ico,action,title) => `<button class="icon-button" data-action="${action}" title="${escapeHTML(title)}" aria-label="${escapeHTML(title)}">${icon(ico)}</button>`;
  const confirmAction = async (message, fn) => {if(!window.confirm(message))return;await fn();};
  const storageInfo = async () => {try{const e=await navigator.storage?.estimate?.();return {usage:e?.usage||0,quota:e?.quota||0,persisted:await navigator.storage?.persisted?.()||false};}catch{return {usage:0,quota:0,persisted:false};}};
  const refreshStorageBadge = async () => {const s=await storageInfo();state.storageEstimate=s;const used=bytesLabel(s.usage);$('#storageMini').textContent=s.quota?`${used}`:used;$('#storageCaption').textContent=s.quota?`of ${bytesLabel(s.quota)} available`:'Browser-managed storage';const percent=s.quota?Math.min(100,s.usage/s.quota*100):0;$('#storageProgress').style.width=`${percent}%`;$('#storageProgress').style.background=percent>90?'var(--red)':'';if(percent>90)$('#storageCaption').textContent='Storage is nearly full';};
  const requestPersistent = async () => {if(!navigator.storage?.persist){toast('Persistent storage is not supported by this browser.',true);return false;}const ok=await navigator.storage.persist();state.settings.persistent=ok;await saveSettings();state.storageEstimate=await storageInfo();toast(ok?'Persistent storage granted by the browser.':"The browser didn't grant persistent storage.",!ok);render();return ok;};
  const showModalForm = ({title,fields,submitText='Save',onSubmit,wide=false}) => {const html=`<form id="modalForm" class="form-grid">${fields.map(f=>`<div class="form-field ${f.full?'full':''}"><label for="f_${f.name}">${escapeHTML(f.label)}</label>${f.kind==='textarea'?`<textarea id="f_${f.name}" name="${f.name}" class="textarea-control" ${f.required?'required':''} placeholder="${escapeHTML(f.placeholder||'')}">${escapeHTML(f.value||'')}</textarea>`:f.kind==='select'?`<select id="f_${f.name}" name="${f.name}" class="select-control">${(f.options||[]).map(o=>`<option value="${escapeHTML(o.value)}" ${String(f.value??'')===String(o.value)?'selected':''}>${escapeHTML(o.label)}</option>`).join('')}</select>`:f.kind==='checkbox'?`<label class="setting-row" style="padding:3px 0;border:0"><span>${escapeHTML(f.hint||'')}</span><input id="f_${f.name}" name="${f.name}" type="checkbox" ${f.value?'checked':''}></label>`:`<input id="f_${f.name}" name="${f.name}" class="input-control" type="${f.kind||'text'}" value="${escapeHTML(f.value||'')}" placeholder="${escapeHTML(f.placeholder||'')}" ${f.required?'required':''}>`}${f.hint&&f.kind!=='checkbox'?`<small class="form-hint">${escapeHTML(f.hint)}</small>`:''}</div>`).join('')}</form>`;modal({title,body:html,wide,footer:`<button class="button button-quiet" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="submit-modal">${submitText}</button>`});$('#modalForm').addEventListener('submit',e=>{e.preventDefault();});$('#modalRoot').dataset.formSubmit='true';$('#modalRoot')._submit=async()=>{const form=$('#modalForm');if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form).entries());$$('input[type=checkbox]',form).forEach(i=>data[i.name]=i.checked);const shouldClose=await onSubmit(data);if(shouldClose!==false)closeModal();};};

  const views = {
    home: () => {
      const docs=liveItems('document').sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||'')).slice(0,4);
      const files=liveItems('file').sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));
      const notes=liveItems('note').sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||'')).slice(0,3);
      const tasks=liveItems('task').filter(t=>!t.completed&&t.dueDate===localDate()).sort((a,b)=>(a.dueTime||'').localeCompare(b.dueTime||'')).slice(0,4);
      const events=liveItems('event').filter(e=>e.startDate===localDate()).sort((a,b)=>(a.startTime||'').localeCompare(b.startTime||'')).slice(0,4);
      const bookmarks=liveItems('bookmark').sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||'')).slice(0,3);
      const usageLabel=liveItems('file').reduce((s,x)=>s+(x.size||0),0);
      const shortcut=(label,sub,ico,action)=>`<button class="shortcut" data-action="${action}"><span class="shortcut-icon">${icon(ico)}</span><span><strong>${label}</strong><small>${sub}</small></span></button>`;
      const rows=(items,type,emptyTitle,ico)=>items.length?`<div class="list">${items.map(x=>`<div class="list-row" data-open-item="${x.id}"><span class="row-icon">${icon(iconForType(type))}</span><span class="row-main"><strong>${escapeHTML(x.name||x.title)}</strong><small>${type==='event'?`${escapeHTML(x.startTime||'All day')} · ${escapeHTML(x.location||'Event')}`:type==='task'?`${escapeHTML(x.dueTime||'')}${x.dueDate?' · '+prettyDate(x.dueDate):''}`:escapeHTML(typeLabel(type))}</small></span><span class="row-trailing">${type==='event'?'':prettyDate(itemDate(x),{month:'short',day:'numeric'})}</span></div>`).join('')}</div>`:empty(emptyTitle,'Items you add will appear here.',ico);
      return `${pageHeading(`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}`,`${monthLabel(new Date(),{weekday:'long',month:'long',day:'numeric'})} · Your private workspace is ready.`,button('Create','plus','quick-add',true))}
        <div class="grid grid-4" style="margin-bottom:15px">${metric('Files',files.length,'Stored in this browser','files')}${metric('Notes',liveItems('note').length,'Ideas and reference','note')}${metric('Open tasks',liveItems('task').filter(t=>!t.completed).length,'Across your task lists','tasks')}${metric('Local file contents',bytesLabel(usageLabel),'Browser-managed storage','shield')}</div>
        <div class="card welcome-card" style="margin-bottom:15px"><div class="eyebrow">Your space, your device</div><h2>Everything in its place.</h2><p>Bring your files, notes, plans, and links together. Your workspace stays in this browser and works offline after it has loaded once.</p>${button('Explore your files','arrowRight','navigate-files',false)}</div>
        <div class="card" style="margin-bottom:15px"><div class="card-head"><h2>Quick create</h2><span class="muted">Start something new</span></div><div class="shortcut-grid">${shortcut('Document','Write something','document','new-document')}${shortcut('Note','Capture a thought','note','new-note')}${shortcut('Task','Add to your list','tasks','new-task')}${shortcut('Event','Plan time','calendarPlus','new-event')}</div></div>
        <div class="grid grid-2"><article class="card"><div class="card-head"><h2>Today’s schedule</h2><button class="text-button" data-nav="calendar">Open calendar ${icon('arrowRight')}</button></div>${rows(events,'event','No events on your calendar today.','calendar')}</article><article class="card"><div class="card-head"><h2>Today’s tasks</h2><button class="text-button" data-nav="tasks">View tasks ${icon('arrowRight')}</button></div>${rows(tasks,'task','A clear day. Add a task when you’re ready.','tasks')}</article><article class="card"><div class="card-head"><h2>Recent documents</h2><button class="text-button" data-nav="documents">All documents ${icon('arrowRight')}</button></div>${rows(docs,'document','Your documents will appear here.','document')}</article><article class="card"><div class="card-head"><h2>Recent notes</h2><button class="text-button" data-nav="notes">All notes ${icon('arrowRight')}</button></div>${rows(notes,'note','Capture a thought and find it here.','note')}</article></div>
        <div class="grid grid-2" style="margin-top:15px"><article class="card"><div class="card-head"><h2>Recently saved links</h2><button class="text-button" data-nav="bookmarks">All bookmarks ${icon('arrowRight')}</button></div>${rows(bookmarks,'bookmark','Saved websites appear here.','bookmark')}</article><article class="card"><div class="card-head"><h2>Privacy at a glance</h2><span class="type-pill event">LOCAL</span></div><p class="footer-note">NEXUS stores your workspace in browser-managed storage for this site. There is no NEXUS account or cloud database. Use Export All to keep a portable backup.</p><div style="margin-top:12px">${button('Storage & privacy','shield','navigate-privacy',false,'button-small')}</div></article></div>`;
    },
    myday: () => {
      const today=localDate();const taskRows=liveItems('task').filter(t=>!t.completed&&(t.myDay||t.dueDate===today||t.dueDate<today)).sort((a,b)=>(a.dueTime||'').localeCompare(b.dueTime||''));const done=liveItems('task').filter(t=>t.completed&&t.completedAt?.slice(0,10)===today);const events=liveItems('event').filter(e=>e.startDate===today).sort((a,b)=>(a.startTime||'').localeCompare(b.startTime||''));const completed=liveItems('task').filter(t=>t.completed).length;const total=liveItems('task').length;
      return `${pageHeading('My Day',`${prettyDate(today,{weekday:'long',month:'long',day:'numeric'})} · A simple plan for today.`,button('Add task','plus','new-task',true))}<div class="grid grid-3" style="margin-bottom:15px">${metric('Tasks for today',taskRows.length,'Including your overdue tasks','tasks')}${metric('Events today',events.length,'On your calendar','calendar')}${metric('Workspace progress',total?`${Math.round(completed/total*100)}%`:'—',`${completed} of ${total} tasks completed`,'check')}</div><div class="grid grid-2"><article class="card"><div class="card-head"><h2>Focus list</h2><span class="muted">Overdue first, then today</span></div>${renderTaskRows(taskRows)}</article><article class="card"><div class="card-head"><h2>Today’s schedule</h2><button class="text-button" data-action="new-event">Add event ${icon('plus')}</button></div>${events.length?`<div class="list">${events.map(e=>`<div class="list-row" data-open-item="${e.id}"><span class="row-icon">${icon('calendar')}</span><span class="row-main"><strong>${escapeHTML(e.name)}</strong><small>${escapeHTML(e.startTime||'All day')}${e.endTime?' – '+escapeHTML(e.endTime):''}${e.location?' · '+escapeHTML(e.location):''}</small></span><span class="row-trailing">${escapeHTML(e.category||'')}</span></div>`).join('')}</div>`:empty('Nothing scheduled','Create an event to reserve time for what matters.','calendar',button('Create event','plus','new-event',true,'button-small'))}</article><article class="card"><div class="card-head"><h2>Completed today</h2><span class="muted">${done.length} finished</span></div>${renderTaskRows(done)}</article><article class="card"><div class="card-head"><h2>Daily progress</h2><span class="muted">Tasks completed</span></div><div style="font-size:25px;font-weight:720;margin:14px 0 7px">${completed}<span style="font-size:12px;color:var(--ink-3);font-weight:500"> / ${total}</span></div><div class="progress-line"><span style="width:${total?Math.round(completed/total*100):0}%"></span></div><p class="footer-note" style="margin-top:10px">Completed tasks stay in your workspace, so you can look back at what you’ve done.</p></article></div>`;
    },
    files: () => {
      const folders=liveItems('folder').filter(f=>f.parentId===state.filesFolder);const files=liveItems('file').filter(f=>f.parentId===state.filesFolder);const current=state.filesFolder?getItem(state.filesFolder):null;
      const folderOptions=[{value:'',label:'Workspace root'},...liveItems('folder').map(f=>({value:f.id,label:f.name}))];
      const actions=`<label class="button button-primary" for="filePicker">${icon('upload')}<span>Upload files</span></label>${button('New folder','plus','new-folder')}`;
      return `${pageHeading('My Files','Your uploads are stored in this browser’s private storage. Pick only the files you want to add.',actions)}<div class="toolbar"><label class="field-search">${icon('search')}<input id="fileSearch" placeholder="Filter this folder" value="${escapeHTML(state.fileQuery||'')}"></label><span class="toolbar-spacer"></span><span class="footer-note">${files.length} files · ${folders.length} folders</span></div><div class="card table-card"><table class="data-table"><thead><tr><th>Name</th><th class="hide-mobile">Type</th><th class="hide-mobile">Size</th><th class="hide-mobile">Modified</th><th></th></tr></thead><tbody>${current?`<tr><td class="primary-cell"><button class="text-button" data-action="folder-up">‹ Back to parent</button></td><td></td><td></td><td></td><td></td></tr>`:''}${folders.map(f=>`<tr><td><button class="text-button" data-open-folder="${f.id}">${icon('folder')} ${escapeHTML(f.name)}</button></td><td class="hide-mobile">Folder</td><td class="hide-mobile">—</td><td class="hide-mobile">${prettyDate(f.updatedAt?.slice(0,10))}</td><td><div class="row-actions">${actionButton('edit',`rename:${f.id}`,'Rename')}${actionButton('trash',`trash:${f.id}`,'Move to Trash')}</div></td></tr>`).join('')}${files.map(f=>`<tr data-file-row="${escapeHTML(f.name.toLowerCase())}"><td class="primary-cell"><span class="row-icon" style="display:inline-grid;vertical-align:middle;margin-right:6px">${icon('file')}</span>${escapeHTML(f.name)}${f.favorite?` <span style="color:var(--amber)">★</span>`:''}</td><td class="hide-mobile">${escapeHTML((f.name.split('.').pop()||'FILE').toUpperCase())}</td><td class="hide-mobile">${bytesLabel(f.size||0)}</td><td class="hide-mobile">${prettyDate(f.updatedAt?.slice(0,10))}</td><td><div class="row-actions">${actionButton('eye',`preview:${f.id}`,'Preview')}${actionButton('download',`download:${f.id}`,'Download')}${actionButton(f.favorite?'star':'star',`favorite:${f.id}`,f.favorite?'Unstar':'Star')}${actionButton('edit',`rename:${f.id}`,'Rename')}${actionButton('trash',`trash:${f.id}`,'Move to Trash')}</div></td></tr>`).join('')}${!folders.length&&!files.length?`<tr><td colspan="5">${empty('This folder is empty','Upload files or create a folder to get started.','files',button('Upload files','upload','pick-files',true,'button-small'))}</td></tr>`:''}</tbody></table></div><p class="footer-note" style="margin-top:11px">OPFS is used for file contents when your browser supports it. IndexedDB is used as a local fallback. Browser storage can be removed when site data is cleared.</p>`;
    },
    documents: () => renderEditorList('document','Documents','Write and keep documents in your workspace.','Create document','new-document'),
    spreadsheets: () => renderEditorList('spreadsheet','Spreadsheets','Simple local spreadsheets with editable cells and basic formulas.','Create spreadsheet','new-spreadsheet'),
    presentations: () => renderEditorList('presentation','Presentations','Build a straightforward slide deck locally.','Create presentation','new-presentation'),
    notes: () => {
      const q=(state.noteQuery||'').toLowerCase();let notes=liveItems('note').filter(n=>!q||searchText(n).includes(q)).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));
      return `${pageHeading('Notes','Quick notes, meeting details, and ideas — saved automatically as you work.',button('New note','plus','new-note',true))}<div class="toolbar"><label class="field-search">${icon('search')}<input id="noteSearch" placeholder="Search notes" value="${escapeHTML(state.noteQuery||'')}"></label><span class="toolbar-spacer"></span><span class="footer-note">${notes.length} notes</span></div>${notes.length?`<div class="grid grid-3">${notes.map(n=>`<article class="item-card note-card" data-open-item="${n.id}"><h3>${escapeHTML(n.name)}</h3><p>${escapeHTML(stripHTML(n.content||'')||'No note content yet.')}</p><footer><span>${prettyDate(n.updatedAt?.slice(0,10))}</span><span>${n.pinned?'Pinned · ':''}${(n.tags||[]).map(t=>`#${escapeHTML(t)}`).join(' ')}</span></footer></article>`).join('')}</div>`:empty('No notes yet','Keep thoughts, checklists, and reference material together.','note',button('Create a note','plus','new-note',true,'button-small'))}`;
    },
    bookmarks: () => {
      const q=(state.bookmarkQuery||'').toLowerCase();const list=liveItems('bookmark').filter(b=>!q||searchText(b).includes(q)).sort((a,b)=>Number(b.favorite)-Number(a.favorite)||(b.updatedAt||'').localeCompare(a.updatedAt||''));
      return `${pageHeading('Bookmarks','Save links for later. NEXUS does not send your URLs to third-party metadata services.',button('Add bookmark','plus','new-bookmark',true))}<div class="toolbar"><label class="field-search">${icon('search')}<input id="bookmarkSearch" placeholder="Search bookmarks" value="${escapeHTML(state.bookmarkQuery||'')}"></label><span class="toolbar-spacer"></span><span class="footer-note">${list.length} saved links</span></div>${list.length?`<div class="bookmark-grid">${list.map(b=>`<article class="link-card"><span class="link-favicon">${icon('bookmark')}</span><span class="link-card-content"><strong>${escapeHTML(b.name)}</strong><small>${escapeHTML(b.url)}</small>${b.description?`<small>${escapeHTML(b.description)}</small>`:''}</span><div class="row-actions">${actionButton('external',`open-url:${b.id}`,'Open website')}${actionButton('edit',`edit-bookmark:${b.id}`,'Edit')}${actionButton('trash',`trash:${b.id}`,'Move to Trash')}</div></article>`).join('')}</div>`:empty('No bookmarks yet','Save a useful website and keep it close at hand.','bookmark',button('Add bookmark','plus','new-bookmark',true,'button-small'))}`;
    },
    collections: () => {const items=liveItems('collection');return `${pageHeading('Collections','Group related workspace items without moving their originals.',button('New collection','plus','new-collection',true))}${items.length?`<div class="collection-grid">${items.map(c=>{const linked=(c.itemIds||[]).map(getItem).filter(x=>x&&!x.deletedAt);return `<article class="collection-card"><div class="card-head"><span class="metric-icon">${icon('collection')}</span><span class="row-actions">${actionButton('edit',`edit-collection:${c.id}`,'Edit collection')}${actionButton('trash',`trash:${c.id}`,'Move to Trash')}</span></div><h3>${escapeHTML(c.name)}</h3><p>${escapeHTML(c.description||'No description')} · ${linked.length} items</p>${linked.slice(0,4).map(x=>`<span class="type-pill">${escapeHTML(typeLabel(x.type))}</span>`).join('')}</article>`}).join('')}</div>`:empty('Collections keep projects together','Create a collection and link files, notes, bookmarks, events, or tasks.','collection',button('Create collection','plus','new-collection',true,'button-small'))}`;},
    trash: () => {const rows=state.items.filter(x=>x.deletedAt).sort((a,b)=>(b.deletedAt||'').localeCompare(a.deletedAt||''));return `${pageHeading('Trash','Restore items you still need, or permanently remove them.',rows.length?button('Empty trash','trash','empty-trash',false,'button-danger'): '')}${rows.length?`<div class="card table-card"><table class="data-table"><thead><tr><th>Name</th><th>Type</th><th class="hide-mobile">Deleted</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td class="primary-cell">${icon(iconForType(x.type))} ${escapeHTML(x.name||x.title||'Untitled')}</td><td>${typeLabel(x.type)}</td><td class="hide-mobile">${prettyDate(x.deletedAt?.slice(0,10))}</td><td><div class="row-actions">${actionButton('restore',`restore:${x.id}`,'Restore')}${actionButton('trash',`purge:${x.id}`,'Delete permanently')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Trash is empty','Deleted items stay here until you remove them permanently.','trash')}`;},
    calendar: () => renderCalendarPage(),
    tasks: () => renderTasksPage(),
    agenda: () => renderAgendaPage(),
    search: () => renderSearchPage(),
    email: () => `${pageHeading('Email','Email connections are intentionally limited in NEXUS Browser.')}
      <div class="grid grid-2"><article class="card"><div class="card-head"><h2>Connect an account</h2><span class="type-pill">NOT AVAILABLE</span></div><div class="info-callout warning">${icon('info')}<span>Secure Gmail and Outlook connections require provider-approved browser OAuth flows and app registrations. This standalone edition has no provider connector configured, so it does not request account credentials or claim to sync email.</span></div><p class="footer-note" style="margin-top:13px">Email synchronization is not available in this build. Proton Mail Bridge, Yahoo Mail, and generic IMAP/SMTP are not reachable from NEXUS Browser.</p></article><article class="card"><div class="card-head"><h2>Keep a local copy</h2></div><p class="footer-note">You can still store email files you choose through My Files. Add .eml or mailbox exports as ordinary files; NEXUS does not parse or sync them in this edition.</p><div style="margin-top:13px">${button('Open My Files','files','navigate-files')}</div></article></div>`,
    settings: () => renderSettingsPage(),
    privacy: () => renderPrivacyPage()
  };

  function renderEditorList(type,title,desc,createText,action){const list=liveItems(type).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));const rows=list.map(x=>`<tr><td class="primary-cell"><button class="text-button" data-open-item="${x.id}">${icon(iconForType(type))} ${escapeHTML(x.name)}</button></td><td class="hide-mobile">${prettyDate(x.updatedAt?.slice(0,10))}</td><td class="hide-mobile">${type==='document'?`${(stripHTML(x.content||'').length)} chars`:type==='spreadsheet'?'Local grid':`${(x.slides||[]).length} slides`}</td><td><div class="row-actions">${actionButton('edit',`open:${x.id}`,'Open')}${actionButton('download',`export:${x.id}`,'Export')}${actionButton('trash',`trash:${x.id}`,'Move to Trash')}</div></td></tr>`).join('');return `${pageHeading(title,desc,button(createText,'plus',action,true))}<div class="card table-card"><table class="data-table"><thead><tr><th>Name</th><th class="hide-mobile">Modified</th><th class="hide-mobile">Details</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan="4">${empty(`No ${title.toLowerCase()} yet`,`Create one and your work stays in this browser.`,iconForType(type),button(createText,'plus',action,true,'button-small'))}</td></tr>`}</tbody></table></div><p class="footer-note" style="margin-top:11px">Editors save workspace records locally. Exported files download to your device when you choose.</p>`;}

  function recurrenceDates(event,start,end){const out=[];const anchor=event.startDate;if(!anchor)return out;const mode=event.repeat||'none';const until=event.repeatUntil||'9999-12-31';const limit=Number(event.repeatCount)||20000;if(mode==='none'){if(anchor>=start&&anchor<=end)out.push(anchor);return out;}let d=new Date(`${anchor}T12:00:00`),count=1;const advance=()=>{if(mode==='daily')d.setDate(d.getDate()+1);else if(mode==='weekdays'){d.setDate(d.getDate()+1);while(d.getDay()===0||d.getDay()===6)d.setDate(d.getDate()+1);}else if(mode==='weekly'||mode==='biweekly')d.setDate(d.getDate()+(mode==='weekly'?7:14));else if(mode==='monthly'){const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);const max=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,max));}else if(mode==='yearly')d.setFullYear(d.getFullYear()+1);};while(localDate(d)<start&&localDate(d)<=until&&count<limit){advance();count++;}while(localDate(d)<=end&&localDate(d)<=until&&count<=limit&&out.length<1200){const key=localDate(d);if(key>=start)out.push(key);advance();count++;}return out;}
  function eventsBetween(start,end){const result=[];const visibleCalendars=new Set(liveItems('calendarGroup').filter(c=>c.visible!==false).map(c=>c.id));for(const e of liveItems('event')){if(e.calendarId&&!visibleCalendars.has(e.calendarId))continue;for(const date of recurrenceDates(e,start,end))result.push({...e,occurrenceDate:date,seriesId:e.id});}return result.sort((a,b)=>(a.occurrenceDate+(a.startTime||'')).localeCompare(b.occurrenceDate+(b.startTime||'')));}
  function renderCalendarPage(){const view=state.calendarView||'month';const activeDate=localDate(state.month);let title=monthLabel(state.month);let start=localDate(new Date(state.month.getFullYear(),state.month.getMonth(),1));let end=localDate(new Date(state.month.getFullYear(),state.month.getMonth()+1,0));let eventList=eventsBetween(start,end);
    if(view==='day'){start=activeDate;end=activeDate;title=prettyDate(activeDate,{weekday:'long',month:'long',day:'numeric',year:'numeric'});eventList=eventsBetween(start,end);}
    else if(view==='week'){const d=new Date(`${activeDate}T12:00:00`);const monday=new Date(d);monday.setDate(d.getDate()-(d.getDay()+6)%7);start=localDate(monday);end=dayOffset(start,6);title=`${prettyDate(start,{month:'short',day:'numeric'})} – ${prettyDate(end,{month:'short',day:'numeric',year:'numeric'})}`;eventList=eventsBetween(start,end);}
    else if(view==='agenda'){start=activeDate;end=dayOffset(start,30);title='Next 30 days';eventList=eventsBetween(start,end);}
    const weekday=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];let body='';
    if(view==='month'){const first=new Date(state.month.getFullYear(),state.month.getMonth(),1);const offset=first.getDay();const days=new Date(state.month.getFullYear(),state.month.getMonth()+1,0).getDate();const total=Math.ceil((offset+days)/7)*7;let cells='';for(let i=0;i<total;i++){const day=i-offset+1;let date;if(day<1)date=localDate(new Date(state.month.getFullYear(),state.month.getMonth(),day));else if(day>days)date=localDate(new Date(state.month.getFullYear(),state.month.getMonth()+1,day-days));else date=localDate(new Date(state.month.getFullYear(),state.month.getMonth(),day));const inMonth=new Date(`${date}T12:00:00`).getMonth()===state.month.getMonth();const current=eventsBetween(date,date).slice(0,3);cells+=`<div class="calendar-day ${inMonth?'':'muted'} ${date===localDate()?'today':''}" data-calendar-date="${date}"><span class="day-number">${Number(date.slice(-2))}</span>${current.map(e=>`<div class="calendar-event" title="${escapeHTML(e.name)}">${e.startTime?escapeHTML(e.startTime)+' ':''}${escapeHTML(e.name)}</div>`).join('')}</div>`;}body=`<div class="calendar-grid">${weekday.map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${cells}</div>`;}
    else if(view==='year'){const y=state.month.getFullYear();body=`<div class="grid grid-3">${Array.from({length:12},(_,i)=>{const d=new Date(y,i,1);return `<button class="card" style="text-align:left;border:1px solid var(--line)" data-action="pick-month:${i}"><strong>${monthLabel(d,{month:'long'})}</strong><div class="month-mini" style="margin-top:8px">${['S','M','T','W','T','F','S'].map(w=>`<span class="week-label">${w}</span>`).join('')}${Array.from({length:new Date(y,i,1).getDay()},()=>'<span></span>').join('')}${Array.from({length:new Date(y,i+1,0).getDate()},(_,n)=>`<span class="${eventsBetween(localDate(new Date(y,i,n+1)),localDate(new Date(y,i,n+1))).length?'has-event':''}">${n+1}</span>`).join('')}</div></button>`}).join('')}</div>`;}
    else{const grouped={};for(const e of eventList)(grouped[e.occurrenceDate]||(grouped[e.occurrenceDate]=[])).push(e);body=Object.keys(grouped).length?Object.keys(grouped).sort().map(date=>`<div style="padding:5px 0 12px"><div class="overline" style="margin:8px 0">${prettyDate(date,{weekday:'long',month:'long',day:'numeric'})}</div>${grouped[date].map(e=>`<div class="list-row" data-open-item="${e.id}"><span class="row-icon">${icon('calendar')}</span><span class="row-main"><strong>${escapeHTML(e.name)}</strong><small>${escapeHTML(e.startTime||'All day')}${e.endTime?' – '+escapeHTML(e.endTime):''}${e.location?' · '+escapeHTML(e.location):''}</small></span><span class="row-trailing">${escapeHTML(e.repeat&&e.repeat!=='none'?'Repeats':'')}</span>${actionButton('edit',`edit-event:${e.id}:${e.occurrenceDate}`,'Edit event')}</div>`).join('')}</div>`).join(''):`<div class="card">${empty('Nothing on the calendar','Create an event to reserve time.','calendar',button('Create event','plus','new-event',true,'button-small'))}</div>`;}
    const calendars=liveItems('calendarGroup');const calendarPanel=`<article class="card"><div class="card-head"><h2>My calendars</h2><button class="text-button" data-action="new-calendar">${icon('plus')} Add calendar</button></div>${calendars.map(c=>`<div class="list-row"><button class="toggle ${c.visible!==false?'on':''}" data-action="toggle-calendar:${c.id}" aria-label="Toggle ${escapeHTML(c.name)}"></button><span class="row-icon" style="color:${safeColor(c.color)}">${icon('calendar')}</span><span class="row-main"><strong>${escapeHTML(c.name)}</strong><small>${liveItems('event').filter(e=>e.calendarId===c.id).length} saved events${c.isDefault?' · Default':''}</small></span><div class="row-actions">${actionButton('edit',`edit-calendar:${c.id}`,'Edit calendar')}${!c.isDefault?actionButton('trash',`delete-calendar:${c.id}`,'Delete calendar'):''}</div></div>`).join('')}</article>`;
    return `${pageHeading('Calendar','Plan in your local timezone. Per-event timezones and single-occurrence recurrence edits are not available in this build.',button('Create event','plus','new-event',true))}<div class="calendar-toolbar"><div class="tabs">${['day','week','month','year','agenda'].map(v=>`<button class="tab-button ${view===v?'active':''}" data-action="calendar-view:${v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><button class="icon-button" data-action="calendar-prev" aria-label="Previous">${icon('chevronLeft')}</button><button class="button button-quiet" data-action="calendar-today">Today</button><button class="icon-button" data-action="calendar-next" aria-label="Next">${icon('chevronRight')}</button><span class="toolbar-spacer"></span><h2>${escapeHTML(title)}</h2></div>${body}<div class="grid grid-2" style="margin-top:13px">${calendarPanel}<article class="card"><div class="card-head"><h2>Calendar reminders</h2><span class="type-pill">OPEN APP</span></div><p class="footer-note">Browser notifications can only be checked while this app is open. Your browser may throttle background tabs. Reminders are never sent through a remote push service.</p><button class="text-button" data-nav="settings">Notification settings ${icon('arrowRight')}</button></article></div><div class="card" style="margin-top:13px;padding:10px 14px"><span class="footer-note">Events follow this browser’s local timezone. ICS/CSV interchange is not included yet. Export regularly to protect your data.</span></div>`;
  }
  function renderTaskRows(tasks){if(!tasks.length)return empty('Nothing here','Tasks you add will show up here.','tasks');return `<div>${tasks.map(t=>`<div class="task-row"><button class="check-button ${t.completed?'done':''}" data-action="toggle-task:${t.id}" aria-label="${t.completed?'Mark incomplete':'Complete task'}">${t.completed?icon('check'):''}</button><div class="task-content"><strong class="${t.completed?'completed':''}" data-open-item="${t.id}">${escapeHTML(t.name)}</strong><div class="task-meta">${t.dueDate?`<span class="${!t.completed&&t.dueDate<localDate()?'overdue':''}">${t.dueDate<localDate()&&!t.completed?'Overdue · ':''}${prettyDate(t.dueDate,{month:'short',day:'numeric'})}${t.dueTime?' · '+escapeHTML(t.dueTime):''}</span>`:'<span>No due date</span>'}<span class="priority-pill priority-${escapeHTML((t.priority||'none').toLowerCase())}">${escapeHTML(t.priority||'None')}</span>${t.myDay?'<span class="type-pill event">My Day</span>':''}</div></div><div class="row-actions">${actionButton('edit',`edit-task:${t.id}`,'Edit task')}${actionButton('trash',`trash:${t.id}`,'Move to Trash')}</div></div>`).join('')}</div>`;}
  function renderTasksPage(){const v=state.taskView||'today';const all=liveItems('task');const day=localDate();let tasks=all.filter(t=>{if(v==='all')return true;if(v==='upcoming')return !t.completed&&t.dueDate&&t.dueDate>day;if(v==='overdue')return !t.completed&&t.dueDate&&t.dueDate<day;if(v==='completed')return t.completed;return !t.completed&&(t.myDay||t.dueDate===day);});tasks.sort((a,b)=>Number(a.completed)-Number(b.completed)||(a.dueDate||'9999').localeCompare(b.dueDate||'9999')||(a.dueTime||'').localeCompare(b.dueTime||''));const views=[['today','Today'],['upcoming','Upcoming'],['overdue','Overdue'],['completed','Completed'],['all','All tasks']];return `${pageHeading('Tasks & Reminders','Plan tasks and browser-open reminders. Subtasks and repeating tasks are not included yet.',button('New task','plus','new-task',true))}<div class="toolbar"><div class="tabs">${views.map(([key,label])=>`<button class="tab-button ${v===key?'active':''}" data-action="task-view:${key}">${label}</button>`).join('')}</div><span class="toolbar-spacer"></span><button class="button button-quiet button-small" data-action="new-task-list">+ List</button></div><div class="grid grid-2"><article class="card"><div class="card-head"><h2>${views.find(x=>x[0]===v)?.[1]||'Tasks'}</h2><span class="muted">${tasks.length} items</span></div>${renderTaskRows(tasks)}</article><article class="card"><div class="card-head"><h2>Task lists</h2><span class="muted">${(state.settings.taskLists||['Personal']).length} lists</span></div><div class="list">${(state.settings.taskLists||['Personal']).map(list=>{const count=all.filter(t=>(t.list||'Personal')===list&&!t.completed).length;return `<div class="list-row"><span class="row-icon">${icon('list')}</span><span class="row-main"><strong>${escapeHTML(list)}</strong><small>${count} open tasks</small></span><span class="row-trailing">${actionButton('plus',`new-task-list:${encodeURIComponent(list)}`,'Add a task to this list')}</span></div>`}).join('')}</div><div class="info-callout" style="margin-top:13px">${icon('bell')}<span>Notifications are shown in this tab while NEXUS is open. They are not guaranteed after you close the app.</span></div></article></div>`;}
  function renderAgendaPage(){const start=localDate();const end=dayOffset(start,21);const events=eventsBetween(start,end);const tasks=liveItems('task').filter(t=>!t.completed&&t.dueDate>=start&&t.dueDate<=end).map(t=>({...t,occurrenceDate:t.dueDate,agendaType:'task'}));const rows=[...events.map(e=>({...e,agendaType:'event'})),...tasks].sort((a,b)=>(a.occurrenceDate+(a.startTime||a.dueTime||'')).localeCompare(b.occurrenceDate+(b.startTime||b.dueTime||'')));const grouped={};for(const row of rows)(grouped[row.occurrenceDate]||(grouped[row.occurrenceDate]=[])).push(row);return `${pageHeading('Agenda','Events and tasks together, grouped by day.',button('Add to plan','plus','quick-add',true))}<div class="card">${rows.length?Object.keys(grouped).map(date=>`<div style="padding-bottom:7px"><div class="overline" style="margin:5px 0">${prettyDate(date,{weekday:'long',month:'long',day:'numeric'})}${date===start?' · Today':''}</div>${grouped[date].map(x=>`<div class="list-row" data-open-item="${x.id}"><span class="row-icon">${icon(x.agendaType==='task'?'tasks':'calendar')}</span><span class="row-main"><strong>${escapeHTML(x.name)}</strong><small>${x.agendaType==='task'?'Task due':(x.startTime||'All day')}${x.dueTime&&x.agendaType==='task'?' · '+escapeHTML(x.dueTime):''}${x.location?' · '+escapeHTML(x.location):''}</small></span><span class="type-pill ${x.agendaType}">${x.agendaType==='task'?'TASK':'EVENT'}</span></div>`).join('')}</div>`).join(''):empty('Your next three weeks are open','Add an event or task to start planning.','agenda',button('Create event','plus','new-event',true,'button-small'))}</div>`;}
  function renderSearchPage(){const q=(state.query||'').trim().toLowerCase();const filter=state.searchFilter;const matches=q?state.items.filter(x=>!x.deletedAt&&searchText(x).includes(q)&&(filter==='all'||x.type===filter)).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||'')):[];const groups={};matches.forEach(x=>(groups[x.type]||(groups[x.type]=[])).push(x));return `${pageHeading('Search','Search across your local workspace. Results are indexed in memory from browser-stored records.', '')}<div class="toolbar"><label class="field-search" style="flex:1;max-width:620px">${icon('search')}<input id="pageSearch" value="${escapeHTML(state.query)}" placeholder="Search files, notes, links, events, and tasks" autofocus></label><select class="select-control" id="searchFilter"><option value="all">All types</option>${['file','document','spreadsheet','presentation','note','bookmark','event','calendarGroup','task','collection'].map(t=>`<option value="${t}" ${filter===t?'selected':''}>${typeLabel(t)}</option>`).join('')}</select></div><div class="card search-results">${!q?`<div class="search-hint">Enter a name or phrase to search your workspace. Search happens on this device.</div>`:matches.length?Object.keys(groups).map(type=>`<div class="result-group">${typeLabel(type)} · ${groups[type].length}</div>${groups[type].map(x=>`<div class="list-row" data-open-item="${x.id}"><span class="row-icon">${icon(iconForType(type))}</span><span class="row-main"><strong>${escapeHTML(x.name||x.title)}</strong><small>${escapeHTML((x.description||stripHTML(x.content||'')||x.url||x.startDate||x.dueDate||'').slice(0,140))}</small></span><span class="row-trailing">${prettyDate(itemDate(x),{month:'short',day:'numeric'})}</span></div>`).join('')}`).join(''):empty('No results found',`Nothing matched “${q}”. Try a shorter search phrase.`,'search')}</div>`;}

  function renderSettingsPage(){const tab=state.settingsTab||'general';const tabs=[['general','Workspace'],['appearance','Appearance'],['storage','Storage'],['data','Import & export'],['notifications','Notifications']];let body='';
    if(tab==='general')body=`<div class="card-head"><h2>Workspace</h2></div><div class="setting-row"><div><strong>Workspace name</strong><p>Choose a name shown in your sidebar and exports.</p></div><div style="display:flex;gap:6px;align-items:center"><input class="input-control" id="workspaceNameInput" style="width:190px" value="${escapeHTML(state.workspaceName)}"><button class="button button-small" data-action="save-workspace-name">Save</button></div></div><div class="setting-row"><div><strong>Edition</strong><p>This app uses browser-managed storage on this device. It has no account system or NEXUS cloud backend.</p></div><span class="type-pill event">NEXUS BROWSER</span></div><div class="setting-row"><div><strong>Application version</strong><p>Portable workspace archive format version 1.</p></div><span class="footer-note">1.0.0</span></div>`;
    if(tab==='appearance')body=`<div class="card-head"><h2>Appearance</h2></div><div class="setting-row"><div><strong>Color theme</strong><p>Applied only to this browser on this device.</p></div><div class="tabs"><button class="tab-button ${localStorage.getItem('nexus-theme')!=='dark'?'active':''}" data-action="theme:light">Light</button><button class="tab-button ${localStorage.getItem('nexus-theme')==='dark'?'active':''}" data-action="theme:dark">Dark</button></div></div><div class="setting-row"><div><strong>Accent color</strong><p>Choose a calm highlight color for controls and active states.</p></div><select class="select-control" id="accentSelect"><option value="#4c68ed">Indigo</option><option value="#25886b">Emerald</option><option value="#bc6b3c">Terracotta</option><option value="#885fc2">Violet</option></select></div><div class="setting-row"><div><strong>Compact sidebar</strong><p>Use a tighter navigation layout on larger screens.</p></div><button class="toggle ${state.settings.compact?'on':''}" data-action="toggle-setting:compact"></button></div>`;
    if(tab==='storage')body=`<div class="card-head"><h2>Storage in this browser</h2><button class="button button-small" data-action="refresh-storage">Refresh</button></div><div class="storage-detail-grid"><div class="storage-detail"><small>Current usage</small><strong id="storageUsage">${bytesLabel(state.storageEstimate?.usage||0)}</strong></div><div class="storage-detail"><small>Available quota</small><strong id="storageQuota">${state.storageEstimate?.quota?bytesLabel(state.storageEstimate.quota):'Not reported'}</strong></div><div class="storage-detail"><small>Persistent storage</small><strong id="storagePersistent">${state.storageEstimate?.persisted?'Granted':'Not granted'}</strong></div></div><div class="progress-track"><span style="width:${state.storageEstimate?.quota?Math.min(100,state.storageEstimate.usage/state.storageEstimate.quota*100):0}%"></span></div><div class="setting-row"><div><strong>Ask the browser to keep this data</strong><p>Persistent storage can reduce automatic eviction. The browser decides whether to grant it; site data can still be cleared manually.</p></div><button class="button button-small" data-action="request-persistent">Request</button></div><div class="setting-row"><div><strong>File storage engine</strong><p>Files use Origin Private File System when supported, with IndexedDB as a fallback.</p></div><span class="footer-note">${navigator.storage?.getDirectory?'OPFS available':'IndexedDB fallback'}</span></div><div class="info-callout warning" style="margin-top:13px">${icon('info')}<span>Workspace data is tied to this browser and site address. Clearing site data, using private browsing, or browser cleanup may remove it. Export backups regularly.</span></div>`;
    if(tab==='data')body=`<div class="card-head"><h2>Portable workspace backups</h2><span class="type-pill event">ON DEVICE</span></div><p class="footer-note" style="margin:0 0 14px">Export all supported workspace records and uploaded file contents to a ZIP archive with a versioned manifest and integrity checks. Email credentials and secrets are never included.</p><div class="grid grid-2"><div class="item-card"><span class="metric-icon">${icon('download')}</span><h3 style="font-size:11px">Export all my data</h3><p class="footer-note">Create a portable .nexus.zip backup of this workspace.</p><button class="button button-primary button-small" data-action="export-all">Export all data</button></div><div class="item-card"><span class="metric-icon">${icon('upload')}</span><h3 style="font-size:11px">Import data</h3><p class="footer-note">Preview a NEXUS archive or workspace JSON file before merging it.</p><button class="button button-small" data-action="import-data">Choose backup</button></div></div><div class="setting-row"><div><strong>Choose a backup folder</strong><p>In supported Chromium browsers, grant a folder for the current session. Otherwise, backups download through the browser.</p></div><button class="button button-small" data-action="choose-backup-folder">${state.backupFolder?'Folder selected':'Choose folder'}</button></div><div class="setting-row"><div><strong>Automatic backups</strong><p>NEXUS Browser cannot run scheduled work while closed. Backups can only be written while this app is open and a granted folder is available.</p></div><span class="type-pill">MANUAL</span></div><div class="info-callout" style="margin-top:13px">${icon('info')}<span>ZIP import accepts NEXUS Browser archives made by this app. Other ZIP formats, ICS/CSV interchange, selective exports, and EML/MBOX parsing are not included yet.</span></div>`;
    if(tab==='notifications')body=`<div class="card-head"><h2>Reminders &amp; notifications</h2><button class="button button-small" data-action="request-notifications">Enable browser notifications</button></div><div class="setting-row"><div><strong>Browser permission</strong><p>Permission status: ${escapeHTML(window.Notification?Notification.permission:'Not supported')}.</p></div><span class="type-pill ${window.Notification&&Notification.permission==='granted'?'event':''}">${window.Notification?escapeHTML(Notification.permission.toUpperCase()):'UNAVAILABLE'}</span></div><div class="setting-row"><div><strong>Open-app reminders</strong><p>Due reminders are checked while NEXUS is open in a tab. Closing the app pauses reminders; no cloud push or background service is used.</p></div><button class="toggle ${state.settings.remindersEnabled!==false?'on':''}" data-action="toggle-setting:remindersEnabled"></button></div><div class="setting-row"><div><strong>Default reminder</strong><p>New events and tasks can use this default lead time.</p></div><select class="select-control" id="defaultReminder"><option value="0">At time of event</option><option value="5">5 minutes before</option><option value="10">10 minutes before</option><option value="15">15 minutes before</option><option value="30">30 minutes before</option><option value="60">1 hour before</option><option value="1440">1 day before</option></select></div><p class="footer-note" style="margin-top:14px">Missed reminders can be listed after you return to the app, but the browser cannot guarantee that notifications fire while it is closed.</p>`;
    return `${pageHeading('Settings','Manage this browser workspace and its local data.') }<div class="settings-layout"><nav class="settings-nav">${tabs.map(([k,l])=>`<button class="${tab===k?'active':''}" data-action="settings-tab:${k}">${l}</button>`).join('')}</nav><article class="card">${body}</article></div>`;}
  function renderPrivacyPage(){const s=state.storageEstimate||{usage:0,quota:0,persisted:false};const types=['file','document','spreadsheet','presentation','note','bookmark','calendarGroup','event','task','collection'];const totals=types.map(t=>[typeLabel(t),liveItems(t).length]);const usedFiles=liveItems('file').reduce((sum,x)=>sum+(x.size||0),0);return `${pageHeading('Privacy & data','See what NEXUS Browser stores and how this edition works.',button('Export all data','download','export-all',true))}<div class="grid grid-3" style="margin-bottom:15px">${metric('Browser storage used',bytesLabel(s.usage),'Current origin storage estimate','shield')}${metric('Uploaded files',bytesLabel(usedFiles),'File content stored locally','files')}${metric('Workspace records',state.items.filter(x=>!x.deletedAt).length,'Across files, notes, planning, and links','collection')}</div><div class="grid grid-2"><article class="card"><div class="card-head"><h2>Where your data lives</h2><span class="type-pill event">THIS DEVICE</span></div><p class="footer-note">Workspace records live in IndexedDB. Uploaded files use the Origin Private File System when available, or IndexedDB fallback. Storage belongs to this browser profile and this site origin; NEXUS cannot open that managed folder in your file explorer.</p><div class="setting-row"><div><strong>Persistent storage requested</strong><p>The browser may still allow the user or cleanup tools to clear site data.</p></div><span class="type-pill">${s.persisted?'GRANTED':'NOT GRANTED'}</span></div><div class="setting-row"><div><strong>Folder access</strong><p>${state.backupFolder?'A backup folder is granted for this session.':'No external folder is currently granted.'}</p></div><span class="type-pill">${state.backupFolder?'SESSION':'NONE'}</span></div></article><article class="card"><div class="card-head"><h2>External connections</h2></div><div class="setting-row"><div><strong>Email accounts</strong><p>No email provider is connected. This build has no provider OAuth connector.</p></div><span class="type-pill">0 CONNECTED</span></div><div class="setting-row"><div><strong>Websites</strong><p>Opening a bookmark visits its site directly. URLs are not sent to a third-party metadata service.</p></div><span class="type-pill">USER ACTION</span></div><div class="setting-row"><div><strong>Analytics &amp; telemetry</strong><p>No analytics or automatic uploads are included.</p></div><span class="type-pill event">OFF</span></div></article><article class="card"><div class="card-head"><h2>Data inventory</h2></div>${totals.map(([name,count])=>`<div class="setting-row"><div><strong>${name}</strong></div><span class="footer-note">${count} items</span></div>`).join('')}</article><article class="card"><div class="card-head"><h2>Browser limitations</h2></div><div class="info-callout warning">${icon('info')}<span>Clearing this site's browser data may permanently delete your workspace. Reminders only run while NEXUS is open. This edition cannot access arbitrary folders or run a local background service.</span></div><div style="display:flex;gap:7px;margin-top:12px">${button('Export backup','download','export-all',true,'button-small')}${button('Storage settings','settings','settings-storage',false,'button-small')}${button('Delete workspace','trash','delete-workspace',false,'button-danger button-small')}</div></article></div>`;}

  function stripHTML(value){const doc=new DOMParser().parseFromString(String(value||''),'text/html');return doc.body.textContent||'';}
  function sanitizeRichHTML(html){const parsed=new DOMParser().parseFromString(String(html||''),'text/html');const allowed=new Set(['P','DIV','BR','H1','H2','H3','B','STRONG','I','EM','U','S','STRIKE','UL','OL','LI','BLOCKQUOTE','A','TABLE','THEAD','TBODY','TR','TD','TH']);const cleanNode=node=>{if(node.nodeType===Node.TEXT_NODE)return document.createTextNode(node.textContent);if(node.nodeType!==Node.ELEMENT_NODE)return document.createDocumentFragment();if(!allowed.has(node.tagName)){const fragment=document.createDocumentFragment();[...node.childNodes].forEach(child=>fragment.append(cleanNode(child)));return fragment;}const el=document.createElement(node.tagName.toLowerCase());if(node.tagName==='A'){const href=node.getAttribute('href')||'';if(/^(https?:|mailto:)/i.test(href))el.setAttribute('href',href);el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');} [...node.childNodes].forEach(child=>el.append(cleanNode(child)));return el;};const result=document.createElement('div');[...parsed.body.childNodes].forEach(n=>result.append(cleanNode(n)));return result.innerHTML;}

  const downloadBlob = (blob,name) => {const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);};
  const startDocument = async () => {const doc=await addItem('document',{name:'Untitled document',content:'<p></p>',favorite:false});openDocument(doc);};
