  const checkReminders = async () => {if(state.settings.remindersEnabled===false)return;const fired=new Set((await metaGet('firedReminders'))||[]);const now=Date.now();let changed=false;for(const item of [...liveItems('event'),...liveItems('task')]){if(item.reminderMins==null)continue;const from=item.type==='event'?item.startDate:item.dueDate;if(!from)continue;const through=dayOffset(localDate(),8);const dates=item.type==='event'?recurrenceDates(item,from,through):[from];for(const date of dates){const target=dateValue(date,item.type==='event'?(item.startTime||(item.allDay?'09:00':'00:00')):(item.dueTime||'09:00'));const due=target-Number(item.reminderMins)*60000;const key=`${item.id}:${date}:${item.startTime||item.dueTime||''}:${item.reminderMins}`;if(due<=now&&due>now-86400000&&!fired.has(key)){fired.add(key);const missed=due<now-5*60000;await addItem('notification',{title:item.name,body:missed?'Missed reminder':`Reminder ${item.reminderMins?`${item.reminderMins} min before`:'now'}`,relatedId:item.id,relatedType:item.type,read:false,reminderKey:key});notifyReminder(item.name,missed?'Missed reminder':`Reminder ${item.reminderMins?`in ${item.reminderMins} minutes`:''}`);changed=true;}}}await metaPut('firedReminders',[...fired].slice(-2000));for(const n of liveItems('notification'))if(n.snoozedUntil&&new Date(n.snoozedUntil).getTime()<=now){n.snoozedUntil=null;n.read=false;await saveItem(n);notifyReminder(n.title,n.body||'Reminder');changed=true;}if(changed){$('#notificationDot').classList.remove('hidden');if(state.section==='home')render();}}

